-- ============================================================
-- ATTENDANCE UPDATE (from the teachers' attendance sheet)  2026-10-07
-- * Sets attended / stage = attendance_recorded on matched leads
--   (matching = teacher + time + student name, then name only).
-- * Never overwrites attendance already entered in the platform
--   (only rows where attended IS NULL are touched) -> safe to re-run.
-- * Attendees that could not be matched to any lead are added as
--   leads named as in the sheet with phone UNKNOWN-nnn and source NULL,
--   so the real attendance count is complete. Fix their phones manually.
-- ============================================================
BEGIN;
DO $$
DECLARE admin_id uuid;
BEGIN
  SELECT id INTO admin_id FROM users ORDER BY created_at ASC LIMIT 1;
  IF admin_id IS NULL THEN RAISE EXCEPTION 'No user found'; END IF;

  WITH u AS (UPDATE crm_leads SET attended = true, stage = 'attendance_recorded', teacher_name = COALESCE(teacher_name, 'اسراء'), lecture_time = COALESCE(lecture_time, '22:00:00'::time), notes = concat_ws(' | ', notes, 'حضور من شيت المعلمين (اسراء): حضر | مطابقة بالاسم: فهد محمد الماضي - راجعها'), updated_at = now() WHERE phone = '966590500022' AND attended IS NULL RETURNING id)
  WITH u AS (UPDATE crm_leads SET attended = true, stage = 'attendance_recorded', teacher_name = COALESCE(teacher_name, 'اسراء'), lecture_time = COALESCE(lecture_time, NULL::time), notes = concat_ws(' | ', notes, 'حضور من شيت المعلمين (اسراء): حضر | مطابقة بالاسم: هيفا وليد الحكير - راجعها'), updated_at = now() WHERE phone = '966559222000' AND attended IS NULL RETURNING id)
